export type TreeNode = { id: string; label: string; kind: string; enabled: boolean; children: readonly TreeNode[] };
export function collectPreorderLabels(root: TreeNode | null): string[] {
  const labels: string[] = [];
  function visit(node: TreeNode): void {
    labels.push(node.label);
    for (const child of node.children) visit(child);
  }
  if (root !== null) visit(root);
  return labels;
}

