problems.solutionCode:
export type TreeNode = { id: string; label: string; kind: string; enabled: boolean; children: readonly TreeNode[] };
export function groupNodeIdsByDepth(root: TreeNode | null): string[][] {
  if (root === null) return [];
  const queue: TreeNode[] = [root];
  let head = 0;
  const levels: string[][] = [];
  while (head < queue.length) {
    const width = queue.length - head;
    const ids: string[] = [];
    for (let i = 0; i < width; i += 1) {
      const node = queue[head];
      head += 1;
      if (node === undefined) continue;
      ids.push(node.id);
      for (const child of node.children) queue.push(child);
    }
    levels.push(ids);
  }
  return levels;
}

