problems.solutionCode:
export type TreeNode = { id: string; label: string; kind: string; enabled: boolean; children: readonly TreeNode[] };
export function findFirstByKind(root: TreeNode | null, kind: string): string | null {
  if (root === null) return null;
  if (root.kind === kind) return root.id;
  for (const child of root.children) {
    const match = findFirstByKind(child, kind);
    if (match !== null) return match;
  }
  return null;
}

